BeforeAll {
    . "./Say.ps1"
}

Describe "Say test cases" {
    It "zero" {
        $got  =  Invoke-Say -Number 0
        $want =  "zero"

        $got | Should -BeExactly $want
    }

    It "one" {
        $got  =  Invoke-Say -Number 1
        $want =  "one"

        $got | Should -BeExactly $want
    }

    It "fourteen" {
